-- ELECTRONICS
('vertex-75-mechanical-keyboard', 'Vertex 75 Mechanical Keyboard', 'electronics', 'Accessories', 'Hot-swappable 75% mechanical keyboard with PBT keycaps.', 'The Vertex 75 delivers a tactile, satisfying typing experience with hot-swappable switches, a gasket-mounted PCB, and dye-sublimated PBT keycaps. USB-C and Bluetooth dual connectivity.', 89.00, 119.00, 'V-EL-001', ARRAY[''], ARRAY['Black', 'White'], ARRAY['https://images.pexels.com/photos/5380584/pexels-photo-5380584.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/28842075/pexels-photo-28842075.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 45, true, true, false, 'active'),
('nimbus-14-ultrabook', 'Nimbus 14 Ultrabook', 'electronics', 'Laptops', 'Ultra-thin laptop with 14-inch retina display and all-day battery.', 'Weighing just 1.2 kg, the Nimbus 14 features a stunning 14-inch Liquid display, 16GB unified memory, and up to 18 hours of battery life. Perfect for work anywhere.', 650.00, 750.00, 'V-EL-002', ARRAY[''], ARRAY['Silver'], ARRAY['https://images.pexels.com/photos/10655906/pexels-photo-10655906.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/14483025/pexels-photo-14483025.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 12, false, true, false, 'active'),
('pulse-watch-series-5', 'Pulse Watch Series 5', 'electronics', 'Wearables', 'Smartwatch with heart-rate, GPS and 7-day battery life.', 'Track workouts, sleep, and heart health with the Pulse Watch Series 5. Features always-on display, built-in GPS, and water resistance to 50 meters.', 100.00, 125.00, 'V-EL-003', ARRAY[''], ARRAY['Black', 'Silver'], ARRAY['https://images.pexels.com/photos/374619/pexels-photo-374619.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/5036927/pexels-photo-5036927.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 60, false, false, true, 'active'),
('aether-pro-wireless-headphones', 'Aether Pro Wireless Headphones', 'electronics', 'Headphones', 'Premium over-ear ANC headphones with 40-hour battery.', 'Immerse yourself in studio-quality sound with adaptive active noise cancellation, plush memory-foam earcups, and a 40-hour battery. USB-C fast charging.', 125.00, 165.00, 'V-EL-004', ARRAY[''], ARRAY['Black', 'White'], ARRAY['https://images.pexels.com/photos/577768/pexels-photo-577768.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/5249311/pexels-photo-5249311.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 80, false, true, true, 'active'),
('cove-wireless-earbuds', 'Cove Wireless Earbuds', 'electronics', 'Headphones', 'Compact earbuds with adaptive transparency and wireless charging case.', 'Cove earbuds deliver rich, balanced sound with adaptive noise cancellation and a pocketable wireless charging case. IPX5 sweat resistance.', 79.00, 99.00, 'V-EL-005', ARRAY[''], ARRAY['White', 'Black'], ARRAY['https://images.pexels.com/photos/3921830/pexels-photo-3921830.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/3921817/pexels-photo-3921817.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 120, false, false, false, 'active'),
